package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen0Test {

    @Test
    public void testCreateNumber_Null() throws NumberFormatException {
        assertNull(NumberUtils.createNumber(null));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_EmptyString() throws NumberFormatException {
        NumberUtils.createNumber("");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_SingleNonDigit() throws NumberFormatException {
        NumberUtils.createNumber("a");
    }

    @Test
    public void testCreateNumber_DoubleDashProtection() throws NumberFormatException {
        assertNull(NumberUtils.createNumber("--123"));
    }

    @Test
    public void testCreateNumber_Hexadecimal() throws NumberFormatException {
        // Assuming createInteger handles 0x
        assertEquals(Integer.valueOf(16), NumberUtils.createNumber("0x10"));
        assertEquals(Integer.valueOf(-16), NumberUtils.createNumber("-0x10"));
    }

    @Test
    public void testCreateNumber_IntegerTypes() throws NumberFormatException {
        assertEquals(Integer.valueOf(123), NumberUtils.createNumber("123"));
        assertEquals(Long.valueOf(123L), NumberUtils.createNumber("123"));
        assertEquals(new BigInteger("12345678901234567890"), NumberUtils.createNumber("12345678901234567890"));
    }

    @Test
    public void testCreateNumber_DecimalTypes() throws NumberFormatException {
        assertEquals(new BigDecimal("123.45"), NumberUtils.createNumber("123.45"));
        assertEquals(123.45, NumberUtils.createNumber("123.45").doubleValue(), 0.001);
        assertEquals(123.45f, NumberUtils.createNumber("123.45f").floatValue(), 0.001f);
    }

    @Test
    public void testCreateNumber_ScientificNotation() throws NumberFormatException {
        assertEquals(new BigDecimal("1.23E2"), NumberUtils.createNumber("1.23E2"));
        assertEquals(123.0, NumberUtils.createNumber("1.23e2").doubleValue(), 0.001);
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidExpPos() throws NumberFormatException {
        // Triggering: if (expPos < decPos)
        NumberUtils.createNumber("1e.5"); 
    }

    @Test
    public void testCreateNumber_LongSuffix() throws NumberFormatException {
        assertEquals(Long.valueOf(123L), NumberUtils.createNumber("123L"));
        assertEquals(Long.valueOf(-123L), NumberUtils.createNumber("-123l"));
        assertEquals(new BigInteger("9223372036854775808"), NumberUtils.createNumber("9223372036854775808L"));
    }

    @Test
    public void testCreateNumber_FloatSuffix() throws NumberFormatException {
        assertEquals(123.45f, NumberUtils.createNumber("123.45F").floatValue(), 0.001f);
    }

    @Test
    public void testCreateNumber_DoubleSuffix() throws NumberFormatException {
        assertEquals(123.45, NumberUtils.createNumber("123.45D").doubleValue(), 0.001);
    }

    @Test
    public void testCreateNumber_FallthroughToBigDecimal() throws NumberFormatException {
        // Test a float that is too big for float type, should fall through to Double or BigDecimal
        // Using a very large number or a specific format that fails float check
        assertEquals(new BigDecimal("123.4567890123456789"), NumberUtils.createNumber("123.4567890123456789"));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidSuffix() throws NumberFormatException {
        NumberUtils.createNumber("123z");
    }

    @Test
    public void testCreateNumber_AllZerosEdgeCase() throws NumberFormatException {
        // Testing logic: if (!(f.isInfinite() || (f.floatValue() == 0.0F && !allZeros)))
        // If input is "0.0", allZeros should be true, so it doesn't trigger the precision error check
        assertEquals(0.0f, NumberUtils.createNumber("0.0f").floatValue(), 0.0f);
        assertEquals(0.0, NumberUtils.createNumber("0.0e0").doubleValue(), 0.0);
    }

    @Test
    public void testCreateNumber_ComplexScientific() throws NumberFormatException {
        // Testing: exp = val.substring(expPos + 1, val.length() - 1);
        // Case where last char is not a digit and there is an exponent
        // e.g., "1.2e3f" -> numeric "1.2e3", lastChar 'f', exp "3"
        assertEquals(1200.0f, NumberUtils.createNumber("1.2e3f").floatValue(), 0.01f);
    }

    @Test
    public void testCreateNumber_LargeIntegerFallthrough() throws NumberFormatException {
        // Test that it tries Integer, then Long, then BigInteger
        assertEquals(new BigInteger("3000000000"), NumberUtils.createNumber("3000000000"));
    }
}
